import 'dart:convert';
import 'dart:io';

import 'package:detoxo/core/design_system/tokens/app_spacing.dart';
import 'package:detoxo/core/design_system/tokens/app_tokens.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

// The Frozen Glass tokens generated by tool/design/gen_design_tokens.dart from
// tool/design/{tokens,recipes}.json. The `--check` run catches drift between
// the JSON and both outputs (app_tokens.g.dart, DxTokens.kt), runs on edited
// JSON pin what the generator rejects, and the spot values pin one case of
// each parser branch.
void main() {
  const slow = Timeout(Duration(minutes: 2));

  test(
    'the generated files match tool/design (gen_design_tokens --check)',
    () async {
      final run = await Process.run('dart', [
        'run',
        'tool/design/gen_design_tokens.dart',
        '--check',
      ]);
      expect(run.exitCode, 0, reason: '${run.stdout}\n${run.stderr}');
    },
    timeout: slow,
  );

  group('gen_design_tokens --check on an edited recipes.json', () {
    // Runs from a scratch root holding the real tokens.json, the edited
    // recipes.json and no outputs, so input that parses reports drift.
    late Directory root;
    setUp(() => root = Directory.systemTemp.createTempSync('design_tokens'));
    tearDown(() => root.deleteSync(recursive: true));

    Future<ProcessResult> check(void Function(Map<String, dynamic>) edit) {
      final design = Directory('${root.path}/tool/design')
        ..createSync(recursive: true);
      File('tool/design/tokens.json').copySync('${design.path}/tokens.json');
      final recipes =
          jsonDecode(File('tool/design/recipes.json').readAsStringSync())
              as Map<String, dynamic>;
      edit(recipes);
      File(
        '${design.path}/recipes.json',
      ).writeAsStringSync(jsonEncode(recipes));
      return Process.run('dart', [
        File('tool/design/gen_design_tokens.dart').absolute.path,
        '--check',
      ], workingDirectory: root.path);
    }

    Map<String, dynamic> token(
      Map<String, dynamic> recipes,
      String group,
      String name,
    ) => ((recipes[group] as Map<String, dynamic>)['tokens'] as List<dynamic>)
        .cast<Map<String, dynamic>>()
        .singleWhere((t) => t['name'] == name);

    test('drift exits 1 and names both outputs', () async {
      final run = await check((_) {});
      expect(run.exitCode, 1, reason: '${run.stderr}');
      expect(run.stderr, contains('app_tokens.g.dart'));
      expect(run.stderr, contains('DxTokens.kt'));
    }, timeout: slow);

    test('light and dark shadows must have the same layer shapes', () async {
      final run = await check((r) {
        // Dark pill-edge drops its inset hairline layer.
        (token(r, 'shadow', 'pill-edge')['value']
                as Map<String, dynamic>)['dark'] =
            'inset 0 1px 0 rgba(255,255,255,0.34)';
      });
      expect(run.exitCode, isNot(0));
      expect(run.stderr, contains('pill-edge: light and dark layers differ'));
    }, timeout: slow);

    test('an override must name a themed colour', () async {
      final run = await check(
        (r) => token(r, 'override', 'ink-3')['name'] = 'ink-9',
      );
      expect(run.exitCode, isNot(0));
      expect(run.stderr, contains('override ink-9: no such themed colour'));
    }, timeout: slow);
  });

  test('a recipes.json override replaces only its theme', () {
    expect(AppTokens.light.ink3, const Color(0xFF7D8699)); // spec #8a93a6
    expect(AppTokens.dark.ink3, const Color(0x6BEBF0FF)); // spec, untouched
  });

  test('rgba alpha rounds half up, as CSS does', () {
    // rgba(235,240,255,0.66): 168.3 → 0xA8; rgba(255,255,255,0.035): 8.9 → 9.
    expect(AppTokens.dark.ink2, const Color(0xA8EBF0FF));
    expect(AppTokens.dark.panelBottom, const Color(0x09FFFFFF));
  });

  test('shadows keep CSS order, inset layers and negative spread', () {
    expect(
      AppTokens.dark.shadowCard.first,
      const DxShadow(
        color: Color(0x1FFFFFFF),
        offset: Offset(0, 1),
        inset: true,
      ),
    );
    expect(
      AppTokens.light.shadowCard[2],
      const DxShadow(
        color: Color(0x52506084),
        offset: Offset(0, 14),
        blur: 32,
        spread: -16,
      ),
    );
  });

  test('a -main/-light/-deep set becomes an aliased AccentPalette', () {
    expect(
      AppTokens.dark.blockAll,
      const AccentPalette(
        Color(0xFF8B7CFF),
        Color(0xFFCDBBFF),
        Color(0xFF5468FF),
      ),
    );
    expect(AppTokens.light.palettes, hasLength(6));
  });

  test('CSS units: % is a fraction, px and deg are plain numbers', () {
    expect(AppTokens.light.kOption, 0.06); // 6%
    expect(AppTokens.dark.kHalo, 0.3); // 30%
    expect(AppTokens.light.kBloomOn, 0.16); // .16
    expect(AppTokens.glassSaturate, 1.8); // 180%
    expect(AppTokens.sheetBlur, 30); // 30px
    expect(AppTokens.iconBaseHue, 214); // 214deg
    expect(AppTokens.accentTextInk, const Color(0xFF0B1020));
  });

  test('type keeps the CSS line box, tracking and tabular figures', () {
    expect(AppTypography.titleXl.height, 40 / 34);
    expect(AppTypography.titleXl.letterSpacing, -1);
    expect(AppTypography.titleXl.fontFamily, 'Manrope');
    expect(
      AppTypography.titleXl.leadingDistribution,
      TextLeadingDistribution.even,
    );
    // The tab header's title: title-xl stepped down to 28/34.
    expect(AppTypography.titleLg.fontSize, 28);
    expect(AppTypography.titleLg.height, 34 / 28);
    expect(AppTypography.titleLg.fontWeight, AppTypography.titleXl.fontWeight);
    expect(AppTypography.label.letterSpacing, 0); // CSS `normal`, not M3's
    expect(AppTypography.number.fontFeatures, [
      const FontFeature.tabularFigures(),
    ]);
    // The eyebrow variant is caption plus 1.6 px tracking.
    expect(AppTypography.eyebrow.fontSize, AppTypography.caption.fontSize);
    expect(AppTypography.eyebrow.fontWeight, AppTypography.caption.fontWeight);
    expect(AppTypography.eyebrow.letterSpacing, 1.6);
  });

  test('a type variant overrides only the fields it names', () {
    // number-lg: number at 58/58 with -2.4 tracking, weight kept.
    expect(AppTypography.numberLg.fontSize, 58);
    expect(AppTypography.numberLg.height, 1);
    expect(AppTypography.numberLg.letterSpacing, -2.4);
    expect(AppTypography.numberLg.fontWeight, AppTypography.number.fontWeight);
    // count / label-strong: only the weight changes.
    expect(AppTypography.count.fontSize, AppTypography.subhead.fontSize);
    expect(AppTypography.count.fontWeight, FontWeight.w700);
    expect(AppTypography.labelStrong.height, AppTypography.label.height);
    expect(AppTypography.labelStrong.fontWeight, FontWeight.w800);
    expect(AppTypography.eyebrowLg.height, 18 / 14);
    expect(AppTypography.eyebrowLg.letterSpacing, 1.8);
  });

  test('Compact Guide session tokens (recipes.json)', () {
    expect(AppTokens.light.control, const Color(0xFFDFE7F8));
    expect(AppTokens.dark.controlOn, const Color(0xFF3E5989));
    expect(AppTokens.dark.startInk, const Color(0xFF0A1430));
    expect(AppTokens.light.startedTo, const Color(0xFF0A7036));
    expect(AppTokens.dark.kScrim0, 0.62);
    expect(AppTokens.light.kSheetGlow, 0.12);
    expect(AppTokens.dark.kAmbDeep, 0.16);
    expect(AppTokens.scrimSaturate, 1.2);
    expect(AppTokens.light.startShadow.last.blur, 24);
    expect(AppRadius.cardSm, 26);
    expect(AppSpacing.sheetSide, 22);
    expect(AppSpacing.headerTop, 54);
  });

  test('tone-<t>-<f> becomes ConfirmTone; spacing and radius alias', () {
    expect(ConfirmTone.critical.c, const Color(0xFFE8366A));
    expect(ConfirmTone.values, [
      ConfirmTone.caution,
      ConfirmTone.critical,
      ConfirmTone.neutral,
    ]);
    expect(AppSpacing.gutter, 20);
    expect(AppRadius.sheet, 40);
  });

  test('accentText and statusText darken in Light only', () {
    const light = AppTokens.light;
    const dark = AppTokens.dark;
    // #3d7bff mixed 40 % toward #0b1020.
    expect(light.accentText(light.brand).toARGB32(), 0xFF2950A6);
    expect(dark.accentText(dark.brand), dark.brand.light);
    // #12a150 mixed 40 % toward #0b1020.
    expect(light.statusText(light.statusOn).toARGB32(), 0xFF0F673D);
    expect(dark.statusText(dark.statusOn), dark.statusOn);
  });

  testWidgets('context.tokens follows the theme brightness', (tester) async {
    late AppTokens seen;
    await tester.pumpWidget(
      MaterialApp(
        theme: ThemeData(brightness: Brightness.dark),
        home: Builder(
          builder: (context) {
            seen = context.tokens;
            return const SizedBox.shrink();
          },
        ),
      ),
    );
    expect(seen, same(AppTokens.dark));
  });
}
